
  // ===== Global role state (shared across all sections) =====
  let userRole = 'guest'; // 'guest' | 'individual' | 'pharmacy'
  let wholesalePreview = false; // guest "peek at wholesale prices" toggle

  // Sticky header
  const header = document.getElementById('siteHeader');
  window.addEventListener('scroll', () => {
    header.classList.toggle('scrolled', window.scrollY > 40);
  });

  // Nav menu panel (floating circular button)
  const menuFab = document.getElementById('menuFab');
  const menuPanel = document.getElementById('menuPanel');
  const menuBackdrop = document.getElementById('menuBackdrop');
  const menuClose = document.getElementById('menuClose');

  function openMenu(){
    menuFab.classList.add('is-open');
    menuFab.setAttribute('aria-expanded', 'true');
    menuPanel.classList.add('is-open');
    menuBackdrop.classList.add('is-open');
  }
  function closeMenu(){
    menuFab.classList.remove('is-open');
    menuFab.setAttribute('aria-expanded', 'false');
    menuPanel.classList.remove('is-open');
    menuBackdrop.classList.remove('is-open');
  }
  menuFab.addEventListener('click', () => {
    menuPanel.classList.contains('is-open') ? closeMenu() : openMenu();
  });
  menuClose.addEventListener('click', closeMenu);
  menuBackdrop.addEventListener('click', closeMenu);
  document.querySelectorAll('.menu-list a').forEach(a => a.addEventListener('click', closeMenu));

  // Reveal on scroll
  const revealEls = document.querySelectorAll('.reveal');
  const io = new IntersectionObserver((entries) => {
    entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('in-view'); });
  }, { threshold: .15 });
  revealEls.forEach(el => io.observe(el));

  // Pulse divider draw-on
  const pulsePath = document.getElementById('pulsePath');
  const pulseIo = new IntersectionObserver((entries) => {
    entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('in-view'); });
  }, { threshold: .4 });
  pulseIo.observe(pulsePath);

  // Products carousel
  const pcData = [
    {
      cat: 'العناية بالفم', title: 'ريفرش غسول الفم اليومي', titleEn: 'Refresh Daily Mouth Wash',
      price: '34.52', desc: 'تركيبة يومية فريدة ومنعشة لنظافة الفم — 300 مل.',
      wholesalePrice: '336', unitsPerCarton: 12, moq: 5,
      img: 'data:image/jpeg;base64,'
    },
    {
      cat: 'مكملات غذائية', title: 'مونوغا بلس أوميغا 3', titleEn: 'Monoga+',
      price: '134.55', desc: 'أقراص قابلة للمضغ بأوميغا 3 من زيت السردين — 30 قطعة.',
      wholesalePrice: '510', unitsPerCarton: 10, moq: 5,
      img: 'data:image/jpeg;base64,'
    },
    {
      cat: 'مكملات غذائية', title: 'مونوغا بلس شراب للأطفال', titleEn: 'Monoga Plus Kids',
      price: '120.75', desc: 'أوميغا 3 مع فيتامين D بطعم محبب للأطفال — 150 مل.',
      wholesalePrice: '384', unitsPerCarton: 12, moq: 5,
      img: 'data:image/jpeg;base64,'
    },
    {
      cat: 'العناية بالفم', title: 'جم كير جل للأسنان واللثة', titleEn: 'Gum Care Tooth Gel',
      price: '30.41', desc: 'جل مضاد للبكتيريا لحماية اللثة والعناية اليومية — 100 مل.',
      wholesalePrice: '504', unitsPerCarton: 24, moq: 5,
      img: 'data:image/jpeg;base64,'
    },
    {
      cat: 'العناية الشخصية', title: 'شارك سبراي للرجال', titleEn: 'Shark Daily Spray For Men',
      price: '50.16', desc: 'بخاخ عناية يومي للرجال بتركيبة فريدة ومنعشة — 30 مل.',
      wholesalePrice: '528', unitsPerCarton: 12, moq: 5,
      img: 'data:image/jpeg;base64,'
    },
    {
      cat: 'مكملات غذائية', title: 'مونوغين كولاجين', titleEn: 'Monogen',
      price: '168.84', desc: 'أمبولات كولاجين بيبتيد وحمض الهيالورونيك — 10×15 مل.',
      wholesalePrice: '630', unitsPerCarton: 6, moq: 5,
      img: 'data:image/jpeg;base64,'
    },
    {
      cat: 'مكملات غذائية', title: 'أريكتين', titleEn: 'Erectin',
      price: '118.45', desc: 'أقراص مضغ مكملة بمستخلصات الجنسنج والماكا والغذاء الملكي — 30 قرص.',
      wholesalePrice: '1050', unitsPerCarton: 10, moq: 5,
      img: 'data:image/jpeg;base64,'
    },
  ];

  // Product detail data (source: معلومات الأدوية - الورقة1.pdf). Pricing is role-aware:
  // guest/individual = per unit, pharmacy = wholesale carton price.
  const productDetails = {
    'مونوقا بلس': { packSize: '30 قرص', usage: 'قرص واحد يومياً بعد الإفطار', detailDesc: 'تركيبة غنية بأوميغا 3 النقي (EPA & DHA) مع فيتامينات A وD والسيلينيوم لدعم صحة القلب والعقل والمناعة.' },
    'ريفرش غسول الفم اليومي': { packSize: '300 مل', usage: 'المضمضة 3 مرات يومياً', detailDesc: 'مضمضة للعناية بالفم تساعد على تقليل البكتيريا المسببة للرائحة والتسوس والتهابات اللثة، مع تركيبة خالية من الكحول.' },
    'مونوجا بلس للأطفال': { packSize: '150 مل', usage: 'ملعقة صغيرة بعد الإفطار', detailDesc: 'تركيبة تجمع أوميغا 3 وفيتامين D لدعم التركيز والذاكرة والنمو وصحة العظام والمناعة، ومناسبة من عمر سنة فأكثر.' },
    'أريكتين': { packSize: '30 قرص', usage: 'قرص مضغ يومياً بعد الإفطار', detailDesc: 'تركيبة طبيعية متكاملة لتعزيز الأداء والخصوبة للرجال، وتضم الجينسنغ والماكا والغذاء الملكي.' },
    'شارك سبراي للرجال': { packSize: 'بخاخ', usage: 'ضع 4–5 قطرات على راحة اليد، دلّك بلطف لمدة 2–3 دقائق، انتظر 10 دقائق ثم اغسل بالماء والصابون قبل العلاقة.', detailDesc: 'بخاخ موضعي مكوّن من زيوت طبيعية يُستخدم قبل العلاقة بـ10–15 دقيقة للمساعدة على تقليل فرط الإحساس وتأخير القذف.' },
    'جم كير جل للأسنان واللثة': { packSize: 'جل', usage: 'يُستخدم من 2 إلى 3 مرات يومياً', detailDesc: 'جل للعناية باللثة والأسنان بتركيبة تحتوي على الكلورهيكسيدين وزيوت طبيعية للمساعدة في التعقيم الموضعي والعناية باللثة.' },
    'مونوجين كولاجين': { packSize: '10 أمبولات', usage: 'أمبول واحد بعد الإفطار', detailDesc: 'تركيبة كولاجين وحمض الهيالورونيك والزنك والسيلينيوم وفيتامين E لدعم المفاصل والبشرة والشعر والأظافر.' }
  };

  function getProductDetails(item){
    const d = productDetails[item.title] || {};
    return {
      ...d,
      packSize: d.packSize || (item.desc.match(/—\s*(.+)\.$/) || [,''])[1] || '—',
      usage: d.usage || 'حسب إرشادات المنتج.',
      detailDesc: d.detailDesc || item.desc
    };
  }

  function titleBlock(item){
    return `
      <div class="pc-title-group">
        <h3>${item.title}</h3>
        <span class="pc-title-en" dir="ltr">${item.titleEn}</span>
      </div>
    `;
  }

  function renderCardPricing(item){
    const details = `<button type="button" class="pc-details-btn" data-detail-title="${item.title}">التفاصيل
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>
    </button>`;

    // Pharmacy: wholesale carton price.
    if (userRole === 'pharmacy') {
      return `
        <span class="wholesale-badge">سعر الجملة للصيدليات</span>
        ${titleBlock(item)}
        <div class="pc-price-row">
          <span class="pc-price">${item.wholesalePrice}</span>
          <span class="cur">ر.س / كرتون (${item.unitsPerCarton} حبة)</span>
        </div>
        <p class="pc-moq">الحد الأدنى للطلب: ${item.moq} كراتين</p>
        <div class="pc-qty-row">
          <span>الكمية (كراتين)</span>
          <input type="number" class="pc-qty-input" min="${item.moq}" value="${item.moq}" step="1">
        </div>
        ${details}
      `;
    }

    // Guest / individual: retail price per unit.
    if (userRole !== 'pharmacy' && wholesalePreview) {
      return `
        <span class="wholesale-badge">سعر الجملة</span>
        ${titleBlock(item)}
        <div class="pc-price-row pc-blurred">
          <span class="pc-price">${item.wholesalePrice}</span>
          <span class="cur">ر.س / كرتون</span>
        </div>
        <p class="pc-moq pc-blurred">الحد الأدنى للطلب: ${item.moq} كراتين</p>
        <div class="pc-wholesale-lock">
          <p>هذه الأسعار خاصة للصيدليات، سجل دخولك بحساب صيدلية لعرضها.</p>
          <button type="button" class="btn btn-primary btn-sm pc-login-cta">تسجيل الدخول</button>
        </div>
        ${details}
      `;
    }

    return `
      ${titleBlock(item)}
      <div class="pc-price-row">
        <span class="pc-price">${item.price}</span>
        <span class="cur">ر.س / حبة</span>
      </div>
      <p class="pc-desc">${item.desc}</p>
      ${details}
    `;
  }

  const pcTrack = document.getElementById('pcTrack');
  const pcDotsWrap = document.getElementById('pcDots');
  const pcPrevBtn = document.getElementById('pcPrev');
  const pcNextBtn = document.getElementById('pcNext');
  const pcStage = document.getElementById('pcStage');
  const pcEmpty = document.getElementById('pcEmpty');
  const catPills = document.querySelectorAll('.cat-pill');
  let pcIndex = 0;
  let pcCards = [];
  let pcDots = [];
  let currentData = pcData;

  function pcBuild(data){
    currentData = data;
    pcIndex = 0;

    if (data.length === 0) {
      pcStage.style.display = 'none';
      pcDotsWrap.style.display = 'none';
      pcEmpty.classList.add('is-visible');
      return;
    }
    pcStage.style.display = '';
    pcDotsWrap.style.display = '';
    pcEmpty.classList.remove('is-visible');

    pcTrack.innerHTML = data.map(item => `
      <div class="pc-card">
        <div class="pc-card-img">
          <span class="pc-card-badge">${item.cat}</span>
          <img src="${item.img}" alt="${item.title}" loading="lazy">
        </div>
        <div class="pc-card-body">
          ${renderCardPricing(item)}
        </div>
      </div>
    `).join('');

    pcDotsWrap.innerHTML = data.map((_, i) => `<button class="pc-dot" data-i="${i}" aria-label="عرض المنتج ${i+1}"></button>`).join('');

    pcCards = Array.from(pcTrack.children);
    pcDots = Array.from(pcDotsWrap.children);
    pcDots.forEach(d => d.addEventListener('click', () => pcGo(parseInt(d.dataset.i, 10))));

    requestAnimationFrame(pcRender);
  }

  function pcRender(){
    if (currentData.length === 0) return;
    const viewportWidth = pcTrack.parentElement.clientWidth;
    // Reset transform first so offsetLeft reflects the untransformed layout position
    pcTrack.style.transform = 'translateX(0px)';
    const activeCard = pcCards[pcIndex];
    const cardCenter = activeCard.offsetLeft + activeCard.offsetWidth / 2;
    const offset = viewportWidth / 2 - cardCenter;
    pcTrack.style.transform = `translateX(${offset}px)`;

    pcCards.forEach((card, i) => {
      card.classList.remove('is-active', 'is-near');
      const dist = Math.abs(i - pcIndex);
      if (dist === 0) card.classList.add('is-active');
      else if (dist === 1) card.classList.add('is-near');
    });
    pcDots.forEach((d, i) => d.classList.toggle('is-active', i === pcIndex));
    pcPrevBtn.disabled = pcIndex === 0;
    pcNextBtn.disabled = pcIndex === currentData.length - 1;
  }

  function pcGo(newIndex){
    pcIndex = Math.max(0, Math.min(currentData.length - 1, newIndex));
    pcRender();
  }

  pcPrevBtn.addEventListener('click', () => pcGo(pcIndex - 1));
  pcNextBtn.addEventListener('click', () => pcGo(pcIndex + 1));
  window.addEventListener('resize', () => pcRender());

  // Category filter pills
  catPills.forEach(pill => {
    pill.addEventListener('click', () => {
      catPills.forEach(p => p.classList.remove('is-active'));
      pill.classList.add('is-active');
      const cat = pill.dataset.cat;
      const filtered = cat === 'all' ? pcData : pcData.filter(item => item.cat === cat);
      pcBuild(filtered);
    });
  });

  // init after layout is ready
  pcBuild(pcData);


  // ===== Product Details Popup =====
  const productDetailsModal = document.getElementById('productDetailsModal');
  const productDetailsBackdrop = document.getElementById('productDetailsBackdrop');
  const productDetailsClose = document.getElementById('productDetailsClose');

  function openProductDetails(title){
    const item = pcData.find(p => p.title === title);
    if (!item || !productDetailsModal) return;
    const details = getProductDetails(item);
    const priceLabel = userRole === 'pharmacy' ? 'سعر الجملة' : 'السعر';
    const price = userRole === 'pharmacy' ? item.wholesalePrice : item.price;
    const unitLabel = userRole === 'pharmacy' ? `ر.س / كرتون (${item.unitsPerCarton} حبة)` : 'ر.س / حبة';

    document.getElementById('detailProductName').textContent = item.title;
    document.getElementById('detailProductEn').textContent = item.titleEn;
    document.getElementById('detailProductDesc').textContent = details.detailDesc;
    document.getElementById('detailProductUsage').textContent = details.usage;
    document.getElementById('detailProductPack').textContent = details.packSize;
    document.getElementById('detailPriceLabel').textContent = priceLabel;
    document.getElementById('detailProductPrice').textContent = price;
    document.getElementById('detailProductUnit').textContent = unitLabel;
    document.getElementById('detailProductImage').src = item.img;
    document.getElementById('detailProductImage').alt = item.title;
    document.getElementById('detailWholesaleNote').style.display = userRole === 'pharmacy' ? 'block' : 'none';

    productDetailsBackdrop.classList.add('is-open');
    productDetailsModal.classList.add('is-open');
    document.body.classList.add('modal-open');
  }

  function closeProductDetails(){
    productDetailsBackdrop?.classList.remove('is-open');
    productDetailsModal?.classList.remove('is-open');
    document.body.classList.remove('modal-open');
  }

  document.addEventListener('click', (event) => {
    const button = event.target.closest('.pc-details-btn');
    if (button) openProductDetails(button.dataset.detailTitle);
    if (event.target.closest('.pc-login-cta')) {
      document.getElementById('openAuth')?.click();
    }
  });
  productDetailsClose?.addEventListener('click', closeProductDetails);
  productDetailsBackdrop?.addEventListener('click', closeProductDetails);
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && productDetailsModal?.classList.contains('is-open')) closeProductDetails();
  });

  // ===== Pharmacy Order Wizard =====
  (function(){
    const modal = document.getElementById('orderModal');
    const backdrop = document.getElementById('orderModalBackdrop');
    const openBtn = document.getElementById('openOrderWizard');
    const closeBtn = document.getElementById('orderModalClose');
    const closeFinalBtn = document.getElementById('closeOrderWizardFinal');
    if (!modal || !openBtn) return;

    const cart = {}; // productIndex -> quantity
    const stepsNav = document.querySelectorAll('.osn-step');
    const panels = document.querySelectorAll('.order-panel');

    function money(n){ return n.toLocaleString('ar-SA') + ' ر.س'; }
    function cartTotal(){
      return Object.entries(cart).reduce((sum, [idx, qty]) => sum + qty * parseFloat(pcData[idx].price), 0);
    }
    function cartCount(){
      return Object.values(cart).reduce((s, q) => s + q, 0);
    }

    function renderProducts(){
      const wrap = document.getElementById('orderProductList');
      wrap.innerHTML = pcData.map((item, idx) => `
        <div class="order-product-row">
          <div class="opr-img"><img src="${item.img}" alt="${item.title}"></div>
          <div class="opr-info">
            <h4>${item.title}</h4>
            <span>${item.price} ر.س</span>
          </div>
          <div class="opr-qty">
            <button type="button" data-act="dec" data-idx="${idx}" aria-label="إنقاص الكمية">−</button>
            <b id="qty-${idx}">${cart[idx] || 0}</b>
            <button type="button" data-act="inc" data-idx="${idx}" aria-label="زيادة الكمية">+</button>
          </div>
        </div>
      `).join('');
      wrap.querySelectorAll('button[data-act]').forEach(btn => {
        btn.addEventListener('click', () => {
          const idx = btn.dataset.idx;
          const current = cart[idx] || 0;
          const next = btn.dataset.act === 'inc' ? current + 1 : Math.max(0, current - 1);
          if (next === 0) delete cart[idx]; else cart[idx] = next;
          document.getElementById('qty-' + idx).textContent = next;
          updateStep1Footer();
        });
      });
      updateStep1Footer();
    }

    function updateStep1Footer(){
      document.getElementById('orderPreviewTotal').textContent = money(cartTotal());
      document.getElementById('toStep2').disabled = cartCount() === 0;
    }

    function renderReview(){
      const wrap = document.getElementById('orderReviewList');
      wrap.innerHTML = Object.entries(cart).map(([idx, qty]) => {
        const item = pcData[idx];
        const line = qty * parseFloat(item.price);
        return `
          <div class="order-review-row">
            <div><div class="orr-name">${item.title}</div><div class="orr-qty">الكمية: ${qty}</div></div>
            <div class="orr-line">${money(line)}</div>
          </div>`;
      }).join('');
      document.getElementById('orderReviewTotal').textContent = money(cartTotal());
    }

    function goToStep(n){
      stepsNav.forEach(s => {
        const sn = parseInt(s.dataset.step, 10);
        s.classList.toggle('is-active', sn === n);
        s.classList.toggle('is-done', sn < n);
      });
      panels.forEach(p => p.classList.remove('is-active'));
      document.getElementById('orderPanel' + n).classList.add('is-active');
      modal.scrollTop = 0;
    }

    function openModal(){
      backdrop.classList.add('is-open');
      modal.classList.add('is-open');
      document.body.style.overflow = 'hidden';
      renderProducts();
      goToStep(1);
    }
    const cancelBackdrop = document.getElementById('orderCancelBackdrop');
    const cancelModal = document.getElementById('orderCancelModal');
    const keepOrderBtn = document.getElementById('keepOrderBtn');
    const confirmCancelOrderBtn = document.getElementById('confirmCancelOrderBtn');

    function closeModal(){
      backdrop.classList.remove('is-open');
      modal.classList.remove('is-open');
      cancelBackdrop?.classList.remove('is-open');
      cancelModal?.classList.remove('is-open');
      document.body.style.overflow = '';
    }

    function hasPendingOrder(){
      return cartCount() > 0 || document.querySelector('.order-panel.is-active')?.id !== 'orderPanel1';
    }

    function showCancelConfirmation(){
      if (!cancelModal || !cancelBackdrop) {
        closeModal();
        return;
      }
      cancelBackdrop.classList.add('is-open');
      cancelModal.classList.add('is-open');
    }

    function confirmCancelOrder(){
      Object.keys(cart).forEach(k => delete cart[k]);
      closeModal();
      goToStep(1);
      renderProducts();
    }

    openBtn.addEventListener('click', openModal);
    closeBtn.addEventListener('click', () => {
      if (hasPendingOrder()) showCancelConfirmation();
      else closeModal();
    });
    backdrop.addEventListener('click', () => {
      if (hasPendingOrder()) showCancelConfirmation();
      else closeModal();
    });
    keepOrderBtn?.addEventListener('click', () => {
      cancelBackdrop?.classList.remove('is-open');
      cancelModal?.classList.remove('is-open');
    });
    confirmCancelOrderBtn?.addEventListener('click', confirmCancelOrder);
    closeFinalBtn.addEventListener('click', () => {
      closeModal();
      Object.keys(cart).forEach(k => delete cart[k]);
    });
    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      if (cancelModal?.classList.contains('is-open')) {
        keepOrderBtn?.click();
        return;
      }
      if (modal.classList.contains('is-open')) {
        if (hasPendingOrder()) showCancelConfirmation();
        else closeModal();
      }
    });

    document.getElementById('toStep2').addEventListener('click', () => { renderReview(); goToStep(2); });
    document.getElementById('backToStep1').addEventListener('click', () => { renderProducts(); goToStep(1); });
    document.getElementById('toStep3').addEventListener('click', () => goToStep(3));
    document.getElementById('backToStep2').addEventListener('click', () => { renderReview(); goToStep(2); });

    // Payment method selection
    const cardFields = document.getElementById('cardFields');
    document.querySelectorAll('input[name="paymentMethod"]').forEach(radio => {
      radio.addEventListener('change', () => {
        document.querySelectorAll('.payment-option').forEach(opt => opt.classList.remove('is-selected'));
        radio.closest('.payment-option').classList.add('is-selected');
        cardFields.classList.toggle('is-visible', radio.value === 'visa');
      });
    });
    const defaultChecked = document.querySelector('input[name="paymentMethod"]:checked');
    if (defaultChecked) defaultChecked.closest('.payment-option').classList.add('is-selected');

    // Submit order -> generate order number + tracking
    document.getElementById('submitOrder').addEventListener('click', () => {
      const orderNum = 'MED-' + Math.floor(100000 + Math.random() * 900000);
      document.getElementById('orderNumber').textContent = orderNum;

      const tkSteps = document.querySelectorAll('.tk-step');
      tkSteps.forEach(s => s.classList.remove('is-done', 'is-current'));
      tkSteps[0].classList.add('is-done');
      tkSteps[1].classList.add('is-current');

      goToStep(4);
    });
  })();

  // ===== Auth Modal (Registration + OTP Login) =====
  (function(){
    const backdrop = document.getElementById('authModalBackdrop');
    const modal = document.getElementById('authModal');
    const openBtn = document.getElementById('openAuthModal');
    const closeBtn = document.getElementById('authModalClose');
    if (!modal || !openBtn) return;

    function openModal(){
      backdrop.classList.add('is-open');
      modal.classList.add('is-open');
      document.body.style.overflow = 'hidden';
    }
    function closeModal(){
      backdrop.classList.remove('is-open');
      modal.classList.remove('is-open');
      document.body.style.overflow = '';
    }
    openBtn.addEventListener('click', () => {
      if (userRole !== 'guest') { setRole('guest'); return; }
      openModal();
    });
    closeBtn.addEventListener('click', closeModal);
    backdrop.addEventListener('click', closeModal);
    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      if (cancelModal?.classList.contains('is-open')) {
        keepOrderBtn?.click();
        return;
      }
      if (modal.classList.contains('is-open')) {
        if (hasPendingOrder()) showCancelConfirmation();
        else closeModal();
      }
    });

    // Main tabs: تسجيل حساب / تسجيل الدخول
    const authTabs = document.querySelectorAll('.auth-tab');
    const authPanels = {
      register: document.getElementById('authPanelRegister'),
      login: document.getElementById('authPanelLogin')
    };
    authTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        authTabs.forEach(t => t.classList.remove('is-active'));
        tab.classList.add('is-active');
        Object.values(authPanels).forEach(p => p.classList.remove('is-active'));
        authPanels[tab.dataset.auth].classList.add('is-active');
      });
    });

    // Account type sub-tabs:  / صيدلية (scoped per group, so register + OTP login don't clash)
    const pharmacyFields = document.getElementById('pharmacyFields');
    document.querySelectorAll('.account-type-tabs').forEach(group => {
      const pillsInGroup = group.querySelectorAll('.acct-pill');
      pillsInGroup.forEach(pill => {
        pill.addEventListener('click', () => {
          pillsInGroup.forEach(p => p.classList.remove('is-active'));
          pill.classList.add('is-active');
          if (group.id === 'accountTypeTabs') {
            const isPharmacy = pill.dataset.acct === 'pharmacy';
            pharmacyFields.classList.toggle('is-visible', isPharmacy);
            pharmacyFields.querySelectorAll('input').forEach(inp => inp.required = isPharmacy);
          }
        });
      });
    });

    // ===== Registration =====
    const registerForm = document.getElementById('registerForm');
    const registerSuccess = document.getElementById('registerSuccess');
    const registerSubmitBtn = registerForm.querySelector('button[type="submit"]');
    const registerPassword = document.getElementById('registerPassword');
    const registerConfirmPassword = document.getElementById('registerConfirmPassword');
    const registerPasswordMatchError = document.getElementById('registerPasswordMatchError');

    function validatePasswordMatch(){
      const mismatch = registerPassword.value !== registerConfirmPassword.value;
      registerPasswordMatchError.classList.toggle('is-visible', mismatch);
      registerConfirmPassword.setCustomValidity(mismatch ? 'كلمتا المرور غير متطابقتين.' : '');
      return !mismatch;
    }
    registerPassword.addEventListener('input', validatePasswordMatch);
    registerConfirmPassword.addEventListener('input', validatePasswordMatch);

    function normalizePhone(value){
      return value.trim().replace(/\s+/g, '').replace(/^\+966/, '0');
    }

    function getStoredUsers(){
      try { return JSON.parse(localStorage.getItem('masarUsers') || '{}'); }
      catch { return {}; }
    }

    function saveUser(user){
      const users = getStoredUsers();
      users[normalizePhone(user.phone)] = user;
      localStorage.setItem('masarUsers', JSON.stringify(users));
    }

    function getUser(phone){
      return getStoredUsers()[normalizePhone(phone)] || null;
    }

    function setButtonLoading(button, loading, loadingText){
      if (!button) return;
      button.disabled = loading;
      button.classList.toggle('is-loading', loading);
      const label = button.querySelector('.btn-label');
      if (label) label.textContent = loading ? loadingText : (button.dataset.defaultText || label.textContent);
    }

    registerSubmitBtn.dataset.defaultText = 'إنشاء الحساب';
    registerForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const formData = new FormData(registerForm);
      const phone = normalizePhone(formData.get('phone') || '');
      const selectedAcct = document.querySelector('#accountTypeTabs .acct-pill.is-active').dataset.acct;
      if (!validatePasswordMatch()) {
        registerConfirmPassword.focus();
        return;
      }
      if (String(formData.get('password') || '').length < 6) {
        registerPassword.setCustomValidity('كلمة المرور يجب أن تكون 6 أحرف على الأقل.');
        registerPassword.reportValidity();
        registerPassword.setCustomValidity('');
        registerPassword.focus();
        return;
      }

      if (!/^05\d{8}$/.test(phone)) {
        alert('يرجى إدخال رقم جوال سعودي صحيح مثل 05xxxxxxxx.');
        return;
      }
      if (getUser(phone)) {
        alert('رقم الجوال مسجل مسبقًا. يمكنك تسجيل الدخول أو استخدام "نسيت كلمة المرور؟".');
        return;
      }

      setButtonLoading(registerSubmitBtn, true, 'جاري إنشاء الحساب...');
      const user = {
        fullName: String(formData.get('fullName') || '').trim(),
        phone,
        email: String(formData.get('email') || '').trim(),
        password: String(formData.get('password') || ''),
        accountType: selectedAcct,
        pharmacyName: String(formData.get('pharmacyName') || '').trim(),
        license: String(formData.get('license') || '').trim(),
        location: String(formData.get('location') || '').trim()
      };

      setTimeout(() => {
        saveUser(user);
        setButtonLoading(registerSubmitBtn, false, 'إنشاء الحساب');
        registerForm.style.display = 'none';
        document.getElementById('accountTypeTabs').style.display = 'none';
        registerSuccess.classList.add('is-visible');
        setRole(selectedAcct);
        setTimeout(closeModal, 1800);
      }, 550);
    });

    // ===== Password visibility =====
    function setupPasswordToggle(buttonId, inputId){
      const button = document.getElementById(buttonId);
      const input = document.getElementById(inputId);
      if (!button || !input) return;
      button.addEventListener('click', () => {
        const visible = input.type === 'text';
        input.type = visible ? 'password' : 'text';
        button.setAttribute('aria-pressed', String(!visible));
        button.setAttribute('aria-label', visible ? 'إظهار كلمة المرور' : 'إخفاء كلمة المرور');
        button.classList.toggle('is-visible', !visible);
      });
    }
    setupPasswordToggle('registerPasswordToggle', 'registerPassword');
    setupPasswordToggle('registerConfirmPasswordToggle', 'registerConfirmPassword');
    setupPasswordToggle('loginPasswordToggle', 'loginPassword');
    setupPasswordToggle('resetPasswordToggle', 'resetPassword');

    // ===== Login with phone + password =====
    const loginForm = document.getElementById('loginForm');
    const loginPhone = document.getElementById('loginPhone');
    const loginPassword = document.getElementById('loginPassword');
    const loginError = document.getElementById('loginError');
    const loginSubmitBtn = document.getElementById('loginSubmitBtn');
    const loginSuccess = document.getElementById('loginSuccess');
    const forgotPasswordBtn = document.getElementById('forgotPasswordBtn');
    const resetPasswordPanel = document.getElementById('resetPasswordPanel');
    const resetPhone = document.getElementById('resetPhone');
    const resetPassword = document.getElementById('resetPassword');
    const resetError = document.getElementById('resetError');
    const resetPasswordSubmitBtn = document.getElementById('resetPasswordSubmitBtn');
    const backToLoginBtn = document.getElementById('backToLoginBtn');

    loginSubmitBtn.dataset.defaultText = 'تسجيل الدخول';

    function showAuthError(element, message){
      element.textContent = message || '';
      element.classList.toggle('is-visible', Boolean(message));
    }

    function resetLoginView(){
      loginForm.hidden = false;
      resetPasswordPanel.hidden = true;
      loginSuccess.classList.remove('is-visible');
      showAuthError(loginError, '');
      showAuthError(resetError, '');
    }

    loginForm.addEventListener('submit', (e) => {
      e.preventDefault();
      showAuthError(loginError, '');
      const phone = normalizePhone(loginPhone.value);
      const password = loginPassword.value;

      if (!/^05\d{8}$/.test(phone)) {
        showAuthError(loginError, 'يرجى إدخال رقم جوال سعودي صحيح.');
        loginPhone.focus();
        return;
      }
      if (!password) {
        showAuthError(loginError, 'يرجى إدخال كلمة المرور.');
        loginPassword.focus();
        return;
      }

      setButtonLoading(loginSubmitBtn, true, 'جاري تسجيل الدخول...');
      setTimeout(() => {
        const user = getUser(phone);
        if (!user || user.password !== password) {
          setButtonLoading(loginSubmitBtn, false, 'تسجيل الدخول');
          showAuthError(loginError, 'رقم الجوال أو كلمة المرور غير صحيحة.');
          loginPassword.focus();
          return;
        }

        setButtonLoading(loginSubmitBtn, false, 'تسجيل الدخول');
        loginForm.hidden = true;
        loginSuccess.classList.add('is-visible');
        setRole(user.accountType || 'individual');
        setTimeout(closeModal, 1500);
      }, 650);
    });

    forgotPasswordBtn.addEventListener('click', () => {
      loginForm.hidden = true;
      resetPasswordPanel.hidden = false;
      showAuthError(loginError, '');
      resetPhone.value = loginPhone.value;
      resetPassword.value = '';
      resetPhone.focus();
    });

    resetPasswordSubmitBtn.addEventListener('click', () => {
      showAuthError(resetError, '');
      const phone = normalizePhone(resetPhone.value);
      const newPassword = resetPassword.value;
      const user = getUser(phone);

      if (!/^05\d{8}$/.test(phone)) {
        showAuthError(resetError, 'يرجى إدخال رقم جوال سعودي صحيح.');
        resetPhone.focus();
        return;
      }
      if (!user) {
        showAuthError(resetError, 'لا يوجد حساب مرتبط بهذا الرقم.');
        resetPhone.focus();
        return;
      }
      if (newPassword.length < 6) {
        showAuthError(resetError, 'يجب أن تتكون كلمة المرور الجديدة من 6 أحرف أو أرقام على الأقل.');
        resetPassword.focus();
        return;
      }

      resetPasswordSubmitBtn.disabled = true;
      resetPasswordSubmitBtn.textContent = 'جاري التحديث...';
      setTimeout(() => {
        user.password = newPassword;
        saveUser(user);
        resetPasswordSubmitBtn.disabled = false;
        resetPasswordSubmitBtn.textContent = 'تحديث كلمة المرور';
        resetPasswordPanel.hidden = true;
        loginForm.hidden = false;
        loginPhone.value = phone;
        loginPassword.value = '';
        showAuthError(loginError, 'تم تحديث كلمة المرور بنجاح. يمكنك الآن تسجيل الدخول.');
        loginPassword.focus();
      }, 600);
    });

    backToLoginBtn.addEventListener('click', resetLoginView);

    // Reset modal to its initial state whenever it's reopened
    openBtn.addEventListener('click', () => {
      registerForm.reset();
      registerForm.style.display = '';
      document.getElementById('accountTypeTabs').style.display = '';
      registerSuccess.classList.remove('is-visible');
      document.querySelectorAll('#accountTypeTabs .acct-pill').forEach(p => p.classList.toggle('is-active', p.dataset.acct === 'individual'));
      pharmacyFields.classList.remove('is-visible');
      pharmacyFields.querySelectorAll('input').forEach(inp => inp.required = false);
      resetLoginView();
      loginForm.reset();
      resetPasswordPanel.hidden = true;
      loginForm.hidden = false;
    });
  })();

  // ===== Role-based UI (individual / pharmacy) =====
  function setRole(role){
    userRole = role;
    wholesalePreview = false;

    const authBtn = document.getElementById('openAuthModal');
    const dashBtn = document.getElementById('dashboardTriggerBtn');
    const wholesaleToggle = document.getElementById('wholesalePreviewToggle');

    if (role === 'pharmacy') {
      authBtn.querySelector('span').textContent = 'تسجيل الخروج';
      dashBtn.style.display = '';
      wholesaleToggle.style.display = 'none';
    } else if (role === 'individual') {
      authBtn.querySelector('span').textContent = 'تسجيل الخروج';
      dashBtn.style.display = 'none';
      wholesaleToggle.style.display = '';
      wholesaleToggle.classList.remove('is-active');
    } else {
      authBtn.querySelector('span').textContent = 'تسجيل الدخول';
      dashBtn.style.display = 'none';
      wholesaleToggle.style.display = '';
      wholesaleToggle.classList.remove('is-active');
    }

    // Re-render the currently visible products with the new role's pricing
    if (typeof pcBuild === 'function' && typeof currentData !== 'undefined') {
      pcBuild(currentData);
    }
  }

  // Wholesale price preview toggle (guest / individual)
  document.getElementById('wholesalePreviewToggle').addEventListener('click', function(){
    wholesalePreview = !wholesalePreview;
    this.classList.toggle('is-active', wholesalePreview);
    pcBuild(currentData);
  });

  // Delegate clicks on the dynamically-rendered "login" CTA inside blurred wholesale cards
  document.getElementById('pcTrack').addEventListener('click', (e) => {
    if (e.target.closest('.pc-login-cta')) {
      document.getElementById('openAuthModal').click();
    }
  });

  // Pharmacy dashboard modal
  (function(){
    const dashBackdrop = document.getElementById('dashboardModalBackdrop');
    const dashModal = document.getElementById('dashboardModal');
    const dashBtn = document.getElementById('dashboardTriggerBtn');
    const dashClose = document.getElementById('dashboardModalClose');
    if (!dashModal || !dashBtn) return;

    dashBtn.addEventListener('click', () => {
      dashBackdrop.classList.add('is-open');
      dashModal.classList.add('is-open');
      document.body.style.overflow = 'hidden';
    });
    function closeDash(){
      dashBackdrop.classList.remove('is-open');
      dashModal.classList.remove('is-open');
      document.body.style.overflow = '';
    }
    dashClose.addEventListener('click', closeDash);
    dashBackdrop.addEventListener('click', closeDash);
    document.getElementById('dashboardStartOrder')?.addEventListener('click', closeDash);
  })();
